 }

 //==================================================================================================
 // Implementations
 //==================================================================================================

 impl KernelPage {
     ///
     /// # Description
     ///
     /// Instantiate a  kernel page.
     ///
     /// # Parameters
     ///
     /// - `kframe`: Underlying kernel frame.
     ///
     /// # Returns
     ///
     /// A new kernel page.
     ///
     pub fn new(kframe: KernelFrame) -> Self {
         Self { kframe }
     }

